def test_percent_split_sets_each_persons_share(run):
    code, _, _ = run(
        "add", "--paid-by", "alice", "--amount", "10.00", "--description", "Dinner",
        "--percent", "alice=50", "--percent", "bob=30", "--percent", "carol=20",
    )  # fmt: skip
    assert code == 0
    assert run("balances")[1] == "alice 5.00\nbob -3.00\ncarol -2.00\n"


@pytest.mark.parametrize("bad", ["bob", "bob=x", "bob=2.5", "=50", "bob=-5"])
def test_malformed_percent_is_rejected(run, bad):
    code, _, err = run(
        "add", "--paid-by", "alice", "--amount", "9", "--description", "x",
        "--percent", "alice=50", "--percent", bad,
    )  # fmt: skip
    assert code == 2
    assert run("list")[1] == ""


def test_percentages_not_adding_to_100_are_rejected(run):
    code, _, err = run(
        "add", "--paid-by", "alice", "--amount", "9", "--description", "x",
        "--percent", "alice=50", "--percent", "bob=40",
    )  # fmt: skip
    assert code == 2
    assert "100" in err
    assert run("list")[1] == ""


def test_with_and_percent_cannot_be_combined(run):
    code, _, _ = run(
        "add", "--paid-by", "alice", "--amount", "9", "--description", "x",
        "--with", "alice", "--percent", "bob=100",
    )  # fmt: skip
    assert code == 2


def test_add_needs_with_or_percent(run):
    code, _, _ = run("add", "--paid-by", "alice", "--amount", "9", "--description", "x")
    assert code == 2
